from author import *
c=C('死锁与银行家算法')
S(c,'死锁、饥饿与普通等待',[T('死锁','一组参与者互相等待，无法自行继续'),T('饥饿','某个任务长期得不到服务'),T('普通阻塞','等待的事件仍可能由外部正常完成')],[P('A拿着打印机等扫描仪，B拿着扫描仪等打印机，谁也不释放，便可能形成死锁。死锁强调一组参与者互相卡住。饥饿则是某个任务总被其他任务挤到后面，系统中别的任务仍可能一直完成工作。两者都可能表现为长时间等，但原因不同。',[1,2],['死锁看相互依赖','饥饿看是否长期得不到服务'],phase='cycle',anchor='A拿着打印机'),P('进程等待磁盘读取时也处于阻塞，但磁盘正常完成就可能解除等待，所以不能把一切阻塞都叫死锁。判断时画出谁持有什么、还需要什么，再看有没有其他参与者能够推进。不要只凭一个进程很久没运行，就断定整个系统发生死锁。',[3],['阻塞是状态，死锁是依赖结果','先检查等待事件是否仍可能发生'],phase='wait',anchor='磁盘正常完成')],['死锁与饥饿'],visual=G('deadlock'))
S(c,'死锁的四个必要条件',[T('资源条件','互斥使用；已占资源通常不能被强行剥夺'),T('申请条件','占有并等待；形成循环等待链'),T('预防思路','设法破坏其中至少一个必要条件')],[P('四个条件可以沿故事逐项检查。资源需要互斥使用，进程拿到资源后继续申请别的资源，已经占有的资源不能随便剥夺，最后等待关系连成环。这些是通常资源死锁模型中的必要条件。只观察到其中一个条件，不能直接推出死锁；描述策略时要明确它破坏了哪一个条件。',[1,2],['四个条件要完整辨认','单个必要条件不等于充分结论']),P('一次性申请全部所需资源，可破坏占有并等待，但可能降低利用率。按统一顺序申请资源，可破坏循环等待。允许回收某些资源则针对不可剥夺条件，但打印到一半的输出并不总能方便回收。预防方法有代价，不能认为破坏互斥适用于所有临界资源。',[3],['统一编号申请，针对循环等待','不同资源允许的回收方式不同'])],['死锁必要条件','死锁预防'])
S(c,'资源分配图怎样判断',[T('请求边','进程 → 资源：还在等待申请'),T('分配边','资源 → 进程：实例已被占有'),T('环的结论','每类单实例时，环与死锁相对应')],[P('资源分配图要先记箭头方向：进程指向资源是请求，资源实例指向进程是分配。先把已经拿到的和还在等待的分开画。若每类资源都只有一个实例，形成等待环就可判定死锁。若某类有多个实例，有环只是需要继续分析的信号，不能直接宣布死锁。',[1,2],['请求和占有方向相反','先数清每类资源的实例数'],phase='edges',anchor='进程指向资源是请求'),P('多实例时，可以尝试找一个剩余需求能被当前可用资源满足的进程。假想让它运行结束，释放已占资源，再找下一位。如果能不断消去所有进程，就不存在该模型下的死锁；如果仍有无法推进的参与者，就继续按检测算法分析。消去的是已满足条件的进程，不是随意删除一条边。',[3],['有多个实例时不能只看有没有环','推进一步后，可用资源会增加'],phase='reduce',anchor='释放已占资源')],['资源分配图'],visual=G('resource_graph'))
S(c,'安全状态与死锁避免',[T('剩余需求','Need＝Max－Allocation'),T('安全序列','存在一种顺序，可让各进程依次完成'),T('关系','不安全不等于已经死锁')],[P('银行家算法先约定每个进程的最大需求。已经分配的叫Allocation，当前还可分配的叫Available，最大值减已分配，得到剩余需求Need。安全检查不是要求所有进程立刻同时拿满资源，而是寻找一种可依次完成、释放资源的顺序。只要能找到一个安全序列，就说明当前状态安全。',[1,2],['最大需求要由题设给出','只需找到一种可完成顺序']),P('不安全表示无法保证按该最大需求约定找到完成顺序，不能直接说此刻已经死锁。避免死锁是在申请资源时，先试探分配，再做安全检查。它与一开始严格破坏必要条件的预防不同，也与死锁发生后再检测和解除不同。选择题先区分处理时机。',[3],['安全检查是一种保证','预防、避免、检测的时机不同'])],['安全状态','银行家算法'])
S(c,'安全序列逐步计算',[T('初始数据','Available＝3；Allocation＝[1,2,1]'),T('最大需求','Max＝[6,5,3]，Need＝[5,3,2]'),T('可用工作量','P1完成：3→5；P0完成：5→6；P2完成：6→7')],[P('本例只有一类资源，三个进程编号零、一、二。当前可用三，已分配分别一、二、一，最大需求六、五、三，故剩余需求五、三、二。先找需求不超过三的参与者，比如P1。假想它完成后，工作变量加回它原来占有的二，变成五。',[1,2],['Need按对应进程相减','完成后加回原有Allocation'],phase='first',anchor='先找需求不超过三的参与者'),P('工作量五已能满足P0的剩余需求五；P0完成再释放原有一，工作量变六。最后P2也能完成，工作量变七。因此P1、P0、P2是一条安全序列。注意不是把最大需求六加回来；试探借出的部分与归还过程在算法里相互抵消，更新Work时加的是原已分配量。',[3],['安全序列不一定唯一','更新Work不能直接加Max'],phase='finish',anchor='工作量五已能满足P0')],['银行家安全算法'],visual=G('banker'))
S(c,'请求检查与死锁解除',[T('申请先过两关','Request ≤ Need，且Request ≤ Available'),T('仍需安全检查','通过前两关，不代表一定允许分配'),T('解除方法','回收资源、撤销进程、回滚等，均有代价')],[P('申请先检查是否超过自己声明的剩余需求，再检查当前可用资源是否足够。两项都通过，只代表可以试探，不代表立即正式分配。继续沿用本例，若P0申请三个，试分配后可用变零，剩余需求变成二、三、二，没有任何进程能够按约定继续完成，因此应撤销试探，保留原状态。',[1,2],['前两项只是必要的请求检查','试分配失败要恢复原状态']),P('如果采用检测和解除，就允许系统先进入可能死锁的状态，再识别参与者并采取措施。撤销进程、回收资源或回滚都可能丢失工作，需要考虑代价和是否会让同一参与者反复成为牺牲者。检测算法看当前实际请求，安全算法还依赖最大需求约定，不能把两张表的含义直接替换。',[3],['检测看当前请求，避免看最大需求保证','解除有成本，不能忽略回滚条件'])],['资源请求算法','死锁检测与解除'])
S(c,'银行家算法练习',[T('已知','Available＝3；Allocation＝[1,2,1]'),T('最大值','Max＝[6,5,3]'),T('申请','P0请求3个资源，是否可以正式分配？')],[P('暂停检查。可用资源三个，已分配一、二、一，最大需求六、五、三。P0现在请求三个资源。请依次检查请求是否超过Need、Available，再写出试分配后的两组数据，判断有没有安全序列。不能只因为手里刚好有三个，就立刻回答可以分配。',[1,2,3],['先求Need，再做试分配','有资源不等于分配后安全'])],['死锁练习'],kind='question')
S(c,'银行家算法练习答案',[T('前两关通过','P0原Need＝5，请求3≤5且3≤Available'),T('试分配','Available＝0；Need＝[2,3,2]'),T('结论','无可推进者，不安全；撤销试分配')],[P('请求没有超过剩余需求，也没有超过可用量，但试分配后Available为零，各进程的剩余需求却都大于零，找不到第一个可完成者，因此状态不安全，不能正式分配。这里应说不安全，并恢复原来的分配数据，而不是说这次请求已经实际制造了死锁。试探阶段和正式提交要分开。',[1,2,3],['请求检查通过后还要查安全性','不安全与已经死锁不是同一句话'])],['死锁练习'],kind='answer')
c=C('内存管理与地址变换')
S(c,'逻辑地址与物理地址',[T('逻辑地址','程序看到的地址空间中的位置'),T('物理地址','实际内存中的位置'),T('地址变换','依赖硬件机制和操作系统维护的信息')],[P('程序写出的地址，不一定就是内存条上的实际位置。进程看到的称逻辑地址或虚拟地址，经过规定机制转换，才得到物理地址。两个进程都访问逻辑地址一千，并不保证访问同一物理位置。加载、链接、重定位等过程负责把程序组织成可执行的运行映像，动态重定位则能在执行时完成地址映射。',[1,2],['相同逻辑地址可能映射到不同位置','地址变换不是简单给所有进程加同一个数'],phase='logical',anchor='两个进程都访问逻辑地址一千'),P('操作系统还要保护各进程的访问范围。最简单的基址与界限模型中，先检查逻辑位置是否越界，再用基址加偏移得到物理位置。访问不合法时应触发保护处理，不能把越界地址继续机械相加。考试给地址表时，先判断表项和边界是否合法，最后才计算数值。',[3],['先合法性检查，再计算','每个进程有自己的管理信息'],phase='physical',anchor='先检查逻辑位置是否越界')],['地址空间','重定位与保护'],visual=G('address'))
S(c,'连续分配与三种适应算法',[T('初始空闲区','按地址顺序：[100,500,200,300,600]'),T('申请212','首次适应选500；最佳适应选300'),T('最坏适应','选择最大空闲区600')],[P('连续分配要求一段所需空间占据连续位置。首次适应沿地址顺序找到第一个够大的洞，最佳适应选够用且最小的洞，最坏适应选最大的洞。本例独立比较一次申请二百一十二：首次选五百，最佳选三百，最坏选六百。不要把三次独立比较误当成连续三次分配。',[1,2],['首次看地址扫描顺序','最佳看够用且最小'],phase='fit',anchor='首次选五百'),P('分配以后，剩余洞大小分别为二百八十八、八十八、三百八十八。释放时，相邻空闲区可以合并；但中间隔着已占空间，就不能直接把容量相加当成一个大洞。总空闲量足够，却找不到足够大的连续区，是外部碎片的典型场景。紧凑搬移可能缓和它，但需要相应重定位支持并付出成本。',[3],['空闲总量够，不代表连续空间够','合并要求物理位置相邻'],phase='remainder',anchor='剩余洞大小')],['连续分配','适应算法与碎片'],visual=G('holes'))
S(c,'分页、页框与页表',[T('划分单位','逻辑空间分为页，物理内存分为页框'),T('页表映射','页号 → 页框号；页内偏移不变'),T('特点','页大小固定，可分散装入；末页可能有内碎片')],[P('分页把逻辑空间切成等大的页，物理内存切成同样大小的页框。一个进程的不同页可以放在不同页框，不必彼此连续。页表负责把页号映射到页框号；页内偏移描述这一页里面的位置，映射前后保留。页号和页框号不相等并不奇怪，这正是需要查表的原因。',[1,2],['页属于逻辑空间，页框属于物理内存','页大小与页框大小相同'],phase='pages',anchor='不同页可以放在不同页框'),P('固定大小页框便于分配，通常不产生连续分区那样的外部碎片，但进程最后一页可能没装满，形成内部碎片。页表本身也要占空间。题目问分页是否完全没有浪费，答案不能简单说是；还要考虑末页、页表和管理开销。先看题目采用的基本分页模型，不把其他混合机制的结论随意套进来。',[3],['基本分页可有内部碎片','页表也占空间'],phase='fragment',anchor='固定大小页框便于分配')],['基本分页'],visual=G('paging'))
S(c,'分页地址计算',[T('题设','页大小1KiB＝1024字节，逻辑地址2500'),T('拆地址','页号2；页内偏移452；页表中2→5'),T('物理地址','5×1024＋452＝5572')],[P('先用逻辑地址除以页大小。二千五百除以一千零二十四，商二、余四百五十二，所以页号是二，偏移是四百五十二。这里的一KiB按二的十次方字节计算。',[1,2],['整除取页号，取余得偏移','页号从0开始'],phase='split',anchor='商二、余四百五十二'),P('页表给出第二号页放在第五号页框，物理地址就是五乘一千零二十四，再加四百五十二，得到五千五百七十二。再用位数检查一遍。页大小是一千零二十四，偏移需要十位；如果逻辑地址总长十六位，剩下六位是页号，可表示六十四页。物理内存若有三十二个页框，页框号需要五位。题目给的是字节地址还是字地址，必须先确认，不能把存储单位跳过去直接拆位。',[3],['页内偏移位数由页大小决定','编址单位必须与页大小统一'],phase='translate',anchor='物理地址就是五乘')],['分页地址计算'],visual=G('page_lookup'))
S(c,'快表TLB与有效访问时间',[T('快表作用','缓存常用的页号到页框号映射'),T('串行模型','查TLB10ns；访问内存100ns；命中率0.9'),T('平均时间','0.9×110＋0.1×210＝120ns')],[P('TLB是地址翻译的缓存，缓存的是映射，不是普通数据内容。命中时直接得到页框号，再访问目标内存；未命中时还要到内存查页表，但这不等于缺页。未命中快表只说明这条映射没有被缓存，页面本身仍可能就在内存里。三个事件：快表未命中、数据缓存未命中、缺页，不能混成一个。',[1],['TLB缓存地址翻译信息','TLB未命中不等于页面不在内存'],phase='hit',anchor='命中时直接得到页框号'),P('本题明确采用串行查找、一级页表且不缺页：查TLB十纳秒，内存一百纳秒。命中花一百一十，未命中需要查页表再取数据，共二百一十。按零点九和零点一加权，得到一百二十纳秒。若题目改成并行查询、多级页表或另含缓存，公式就要重新按路径计算。',[2,3],['先列每条访问路径，再按概率加权','不要把本模型公式当成所有硬件通式'],phase='miss',anchor='未命中需要查页表再取数据')],['TLB','有效访问时间'],visual=G('tlb'))
S(c,'多级页表怎样节约空间',[T('32位地址、4KiB页','页号20位，偏移12位'),T('单级页表','2²⁰个表项，每项4字节，共4MiB'),T('二级例子','目录10位＋表内10位＋偏移12位')],[P('三十二位字节地址配四KiB页，偏移占十二位，页号还剩二十位。若单级页表每项四字节，全部表项需要四MiB。二级页表把页号继续拆成目录索引和页内表索引，本例各十位。每个二级页表一千零二十四项，正好占四KiB，便于按页组织。',[1,2],['先算页数，再乘表项大小','字节与位的单位分开']),P('节约来自稀疏使用：某段虚拟地址完全没有用到，就可以不为它建立对应的下级页表，而不是每一项突然变得不占空间。如果整个空间都用满，多级结构还会增加目录等额外开销；查询也可能多访问几次内存。因此不要说多级页表在任何情况下一定比单级表占用更小、访问更快。',[3],['未使用区间可省下级页表','多级结构不是无条件更小更快'])],['多级页表'])
S(c,'分段与段页式',[T('分段地址','段号＋段内偏移，段长度可不同'),T('合法性','偏移必须小于段长，再用段基址相加'),T('段页式','先找段内页表，再按页号与偏移转换')],[P('分段按程序的逻辑部分组织，例如代码段、数据段，段长度可以不同。段表记录基址和长度。若某段基址四千、长度一千二百，偏移八百合法，物理位置四千八百；偏移一千三百则越界，不能照样相加。基本分段常有外部碎片，和固定大小基本分页的末页内碎片要分开。',[1,2],['分段强调逻辑单位、长度可变','偏移小于段长才合法'],phase='segment',anchor='偏移八百合法'),P('段页式把两种思想组合起来：先按段号定位这一段的页表，再用段内页号找页框，最后加页内偏移。它不是把同一个地址随便查两张无关的表。地址由哪些字段组成、各表项记录什么，需要照题设画出访问链。共享、保护的粒度和查表开销，也要分别分析。',[3],['先段后页，表有明确层次关系','偏移字段的含义不能串层'],phase='segment_page',anchor='先按段号定位')],['分段','段页式'],visual=G('segments'))
S(c,'地址变换练习',[T('题设','页大小1024字节，逻辑地址3500'),T('页表','页号3映射到页框7，访问合法且不缺页'),T('问题','页号、偏移和物理地址分别是多少？')],[P('暂停计算。仍按字节编址，页大小一千零二十四，逻辑地址三千五百，第三号页映射到第七号页框。先写商和余数，再查表替换页号，最后合成物理地址。题目已经说明访问合法且不缺页，因此本题只算地址，不额外加入磁盘读取时间。',[1,2,3],['除数用1024，不是1000','偏移不能随着页框号一起替换'])],['地址变换练习'],kind='question')
S(c,'地址变换练习答案',[T('拆分','3500＝3×1024＋428'),T('转换','页号3 → 页框7；偏移保持428'),T('物理地址','7×1024＋428＝7596')],[P('页号三，偏移四百二十八。查页表把三替换成七，物理地址为七乘一千零二十四，加四百二十八，等于七千五百九十六。检查结果仍位于第七号页框内部，而且偏移小于一千零二十四。如果你得到的偏移大于等于页大小，就说明整除或取余出错。',[1,2,3],['偏移范围是0到页大小减1','换的是页号，不是偏移'])],['地址变换练习'],kind='answer')

